CREATE TABLE IF NOT EXISTS users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS contracts(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,title VARCHAR(255) NOT NULL,contract_type VARCHAR(60) NOT NULL DEFAULT 'other',parties VARCHAR(500) NULL,description TEXT NULL,start_date DATE NULL,expiry_date DATE NULL,renewal_terms TEXT NULL,notice_period_days SMALLINT UNSIGNED NULL,status ENUM('draft','active','expired','terminated','archived') NOT NULL DEFAULT 'draft',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(user_id,status),INDEX(expiry_date),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS contract_versions(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,contract_id INT UNSIGNED NOT NULL,version_label VARCHAR(40) NOT NULL,original_name VARCHAR(255) NULL,stored_name CHAR(40) NULL,file_ext ENUM('pdf','docx','txt','manual') NOT NULL,file_hash CHAR(64) NULL,extracted_text MEDIUMTEXT NULL,extraction_status ENUM('pending','success','partial','failed','ocr_required','manual') NOT NULL DEFAULT 'pending',extraction_method VARCHAR(60) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(contract_id,file_hash),FOREIGN KEY(contract_id) REFERENCES contracts(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS analysis_results(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,version_id INT UNSIGNED NOT NULL,status ENUM('completed','failed','unavailable') NOT NULL,method VARCHAR(60) NOT NULL,summary_json JSON NULL,risk_score TINYINT UNSIGNED NULL,error_message VARCHAR(500) NULL,analyzed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(version_id) REFERENCES contract_versions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS clauses(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,version_id INT UNSIGNED NOT NULL,category VARCHAR(40) NOT NULL,text MEDIUMTEXT NOT NULL,source_ref VARCHAR(80) NULL,method VARCHAR(40) NOT NULL DEFAULT 'rule',FOREIGN KEY(version_id) REFERENCES contract_versions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS risk_findings(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,analysis_id INT UNSIGNED NOT NULL,category ENUM('financial','termination','privacy','ip') NOT NULL,level ENUM('low','medium','high') NOT NULL,explanation TEXT NOT NULL,clause_text TEXT NULL,source_ref VARCHAR(80) NULL,confidence ENUM('low','medium','high') NULL,review_status ENUM('unreviewed','accepted','dismissed') NOT NULL DEFAULT 'unreviewed',FOREIGN KEY(analysis_id) REFERENCES analysis_results(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS obligation_suggestions(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,version_id INT UNSIGNED NOT NULL,description TEXT NOT NULL,responsible_party VARCHAR(150) NULL,due_date DATE NULL,trigger_note VARCHAR(255) NULL,supporting_text TEXT NULL,source_ref VARCHAR(80) NULL,method VARCHAR(40) NOT NULL,review_status ENUM('pending','confirmed','rejected') NOT NULL DEFAULT 'pending',FOREIGN KEY(version_id) REFERENCES contract_versions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS obligations(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,contract_id INT UNSIGNED NOT NULL,suggestion_id INT UNSIGNED NULL,description TEXT NOT NULL,responsible_party VARCHAR(150) NULL,due_date DATE NULL,priority ENUM('low','medium','high') NOT NULL DEFAULT 'medium',status ENUM('pending','in_progress','completed','cancelled') NOT NULL DEFAULT 'pending',source_clause TEXT NULL,notes TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(contract_id,status),INDEX(due_date),FOREIGN KEY(contract_id) REFERENCES contracts(id) ON DELETE CASCADE,FOREIGN KEY(suggestion_id) REFERENCES obligation_suggestions(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payments(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,contract_id INT UNSIGNED NOT NULL,obligation_id INT UNSIGNED NULL,expected_amount DECIMAL(14,2) NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'INR',due_date DATE NULL,amount_paid DECIMAL(14,2) NOT NULL DEFAULT 0.00,paid_on DATE NULL,status ENUM('pending','partial','paid','overdue','cancelled') NOT NULL DEFAULT 'pending',reference VARCHAR(190) NULL,notes TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(contract_id,status),INDEX(due_date),FOREIGN KEY(contract_id) REFERENCES contracts(id) ON DELETE CASCADE,FOREIGN KEY(obligation_id) REFERENCES obligations(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reminders(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,contract_id INT UNSIGNED NOT NULL,kind ENUM('expiry','renewal','obligation','payment') NOT NULL,ref_id INT UNSIGNED NOT NULL DEFAULT 0,remind_on DATE NOT NULL,status ENUM('scheduled','sent','dismissed') NOT NULL DEFAULT 'scheduled',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(contract_id,kind,ref_id,remind_on),FOREIGN KEY(contract_id) REFERENCES contracts(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notifications(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,contract_id INT UNSIGNED NULL,reminder_id INT UNSIGNED NULL UNIQUE,message VARCHAR(500) NOT NULL,is_read TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,is_read),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(contract_id) REFERENCES contracts(id) ON DELETE CASCADE,FOREIGN KEY(reminder_id) REFERENCES reminders(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS review_notes(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,contract_id INT UNSIGNED NOT NULL,user_id INT UNSIGNED NOT NULL,body TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(contract_id) REFERENCES contracts(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS review_checklist_items(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,contract_id INT UNSIGNED NOT NULL,label VARCHAR(255) NOT NULL,is_done TINYINT(1) NOT NULL DEFAULT 0,FOREIGN KEY(contract_id) REFERENCES contracts(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS chat_messages(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,contract_id INT UNSIGNED NOT NULL,user_id INT UNSIGNED NOT NULL,role ENUM('user','assistant') NOT NULL,content TEXT NOT NULL,sources_json JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(contract_id,user_id),FOREIGN KEY(contract_id) REFERENCES contracts(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS activity_logs(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NULL,contract_id INT UNSIGNED NULL,action VARCHAR(60) NOT NULL,detail VARCHAR(500) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,created_at),INDEX(contract_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(contract_id) REFERENCES contracts(id) ON DELETE SET NULL) ENGINE=InnoDB;
